package contracts

import (
	"bytes"
	"compress/flate"
	_ "embed"
	"encoding/binary"
	"hash/crc32"
	"io"
	"sync"
)

// ada_idna_tables.deflate is ada v4.0.0's table blob (src/table_blob.inc,
// raw DEFLATE, generated by ada's scripts/pack_tables.py from the Unicode
// data files), copied byte for byte by scripts/parity/extract-ada-idna.ts.
// ada is the URL parser of the Node build (Node v24.21.0, process.versions
// .ada 4.0.0); it is MIT OR Apache-2.0 licensed, see
// ada_idna_tables.LICENSE. The blob holds the tables ada's IDNA code reads:
// the UTS #46 mapping (IDNA 17.0.0), ada's normalization tables (canonical
// decompositions, combining classes and compositions, which stop at
// Unicode 15.1), its Bidi classes and its combining-mark ranges (which stop
// at Unicode 13). zod's z.httpUrl() sees the hostname those tables give, so
// the port reads the same tables rather than Go's Unicode 17 ones.
//
//go:embed ada_idna_tables.deflate
var adaTablesDeflate []byte

// The blob layout, from ada v4.0.0's src/table_blob.inc (the extractor
// checks these against the source it copies from).
const (
	adaCompressedSize     = 62377
	adaUncompressedSize   = 224608
	adaUncompressedCRC32  = 0x6F4A6B2E
	adaDecompositionRows  = 67
	adaDecompositionCols  = 257
	adaCCCRows            = 67
	adaCCCCols            = 256
	adaCompositionRows    = 67
	adaCompositionCols    = 257
	adaOffIDNAStage1      = 0
	adaCountIDNAStage1    = 3282
	adaOffIDNAStage2      = 6564
	adaCountIDNAStage2    = 11456
	adaOffIDNABoolBlocks  = 29480
	adaCountIDNABool      = 225
	adaOffIDNAUTF8Maps    = 31280
	adaCountIDNAUTF8Maps  = 17383
	adaOffDecompIndex     = 48663
	adaOffDecompBlock     = 53016
	adaCountDecompBlock   = 17219
	adaOffDecompData      = 87456
	adaCountDecompData    = 9102
	adaOffCCCIndex        = 123864
	adaOffCCCBlock        = 128216
	adaCountCCCBlock      = 17152
	adaOffCompIndex       = 145368
	adaOffCompBlock       = 149720
	adaCountCompBlock     = 17219
	adaOffCompData        = 184160
	adaCountCompData      = 1883
	adaOffDirStart        = 209244
	adaOffDirFinal        = 215040
	adaOffDirValue        = 220836
	adaDirTableCount      = 1449
	adaOffCombiningFlat   = 222288
	adaCountCombiningFlat = 580
	adaIndexCount         = 4352 // one row index per 256 code points
)

// ada's IDNA mapping lookup (src/mapping_tables.cpp): a two-level table over
// [0, idnaLowRangeEnd); above it only U+E0100..U+E01EF is ignored.
const (
	idnaValid            = 0xFFFF
	idnaDisallowed       = 0xFFFE
	idnaIgnored          = 0x0000
	idnaBoolFlag         = 0x8000
	idnaBlockBits        = 6
	idnaBlockMask        = 63
	idnaLowRangeEnd      = 0x33480
	idnaHighIgnoredStart = 0xE0100
	idnaHighIgnoredEnd   = 0xE01F0
)

// adaIDNATables is the inflated blob, cut into its sections.
type adaIDNATables struct {
	stage1       []uint16
	stage2       []uint16
	boolBlocks   []uint64
	utf8Mappings []byte
	decompIndex  []byte
	decompBlock  []uint16
	decompData   []rune
	cccIndex     []byte
	cccBlock     []byte
	compIndex    []byte
	compBlock    []uint16
	compData     []rune
	dirStart     []uint32
	dirFinal     []uint32
	dirValue     []byte
	combining    []uint32 // [start, end] pairs
}

var (
	adaTablesOnce sync.Once
	adaTablesData *adaIDNATables
)

// adaTables is the inflated table set, or nil when the embedded blob does
// not inflate to ada's recorded size and CRC32, in which case every
// non-ASCII host fails, as it does in ada (ensure_tables).
func adaTables() *adaIDNATables {
	adaTablesOnce.Do(func() { adaTablesData = loadAdaTables(adaTablesDeflate) })
	return adaTablesData
}

func loadAdaTables(compressed []byte) *adaIDNATables {
	if len(compressed) != adaCompressedSize {
		return nil
	}
	raw, err := io.ReadAll(io.LimitReader(flate.NewReader(bytes.NewReader(compressed)), adaUncompressedSize+1))
	if err != nil || len(raw) != adaUncompressedSize || crc32.ChecksumIEEE(raw) != adaUncompressedCRC32 {
		return nil
	}
	le := binary.LittleEndian
	u16 := func(off, n int) []uint16 {
		out := make([]uint16, n)
		for i := range out {
			out[i] = le.Uint16(raw[off+2*i:])
		}
		return out
	}
	u32 := func(off, n int) []uint32 {
		out := make([]uint32, n)
		for i := range out {
			out[i] = le.Uint32(raw[off+4*i:])
		}
		return out
	}
	runes := func(off, n int) []rune {
		out := make([]rune, n)
		for i := range out {
			out[i] = rune(le.Uint32(raw[off+4*i:]))
		}
		return out
	}
	boolBlocks := make([]uint64, adaCountIDNABool)
	for i := range boolBlocks {
		boolBlocks[i] = le.Uint64(raw[adaOffIDNABoolBlocks+8*i:])
	}
	t := &adaIDNATables{
		stage1:       u16(adaOffIDNAStage1, adaCountIDNAStage1),
		stage2:       u16(adaOffIDNAStage2, adaCountIDNAStage2),
		boolBlocks:   boolBlocks,
		utf8Mappings: raw[adaOffIDNAUTF8Maps : adaOffIDNAUTF8Maps+adaCountIDNAUTF8Maps],
		decompIndex:  raw[adaOffDecompIndex : adaOffDecompIndex+adaIndexCount],
		decompBlock:  u16(adaOffDecompBlock, adaCountDecompBlock),
		decompData:   runes(adaOffDecompData, adaCountDecompData),
		cccIndex:     raw[adaOffCCCIndex : adaOffCCCIndex+adaIndexCount],
		cccBlock:     raw[adaOffCCCBlock : adaOffCCCBlock+adaCountCCCBlock],
		compIndex:    raw[adaOffCompIndex : adaOffCompIndex+adaIndexCount],
		compBlock:    u16(adaOffCompBlock, adaCountCompBlock),
		compData:     runes(adaOffCompData, adaCountCompData),
		dirStart:     u32(adaOffDirStart, adaDirTableCount),
		dirFinal:     u32(adaOffDirFinal, adaDirTableCount),
		dirValue:     raw[adaOffDirValue : adaOffDirValue+adaDirTableCount],
		combining:    u32(adaOffCombiningFlat, adaCountCombiningFlat),
	}
	if !t.consistent() {
		return nil
	}
	return t
}

// consistent checks the invariants ada's C++ relies on without checking, so
// that no Go lookup can index out of range: every stage-1 reference lands
// inside its stage, and every decomposition and composition row is
// non-decreasing and inside its data.
func (t *adaIDNATables) consistent() bool {
	for _, ref := range t.stage1 {
		if ref&idnaBoolFlag != 0 {
			if int(ref&^idnaBoolFlag) >= len(t.boolBlocks) {
				return false
			}
		} else if int(ref)+idnaBlockMask >= len(t.stage2) {
			return false
		}
	}
	rowsOK := func(block []uint16, rows int, shift uint, data int) bool {
		for r := 0; r < rows; r++ {
			row := block[r*257 : r*257+257]
			for i := 0; i+1 < len(row); i++ {
				lo, hi := int(row[i]>>shift), int(row[i+1]>>shift)
				if hi < lo || hi > data {
					return false
				}
			}
		}
		return true
	}
	return rowsOK(t.decompBlock, adaDecompositionRows, 2, len(t.decompData)) &&
		rowsOK(t.compBlock, adaCompositionRows, 0, len(t.compData))
}

// lookup is ada's idna_lookup: idnaValid, idnaDisallowed, or an offset into
// utf8Mappings of the NUL-terminated UTF-8 mapping (idnaIgnored is the
// empty one at offset 0).
func (t *adaIDNATables) lookup(cp uint32) uint16 {
	if cp < idnaLowRangeEnd {
		ref := t.stage1[cp>>idnaBlockBits]
		if ref&idnaBoolFlag != 0 {
			bit := uint32(ref&^idnaBoolFlag)<<idnaBlockBits + cp&idnaBlockMask
			if t.boolBlocks[bit>>6]>>(bit&63)&1 != 0 {
				return idnaValid
			}
			return idnaDisallowed
		}
		return t.stage2[uint32(ref)+cp&idnaBlockMask]
	}
	if cp >= idnaHighIgnoredStart && cp < idnaHighIgnoredEnd {
		return idnaIgnored
	}
	return idnaDisallowed
}

// mapRunes is ada's map: UTS #46 mapping, false at the first disallowed
// code point.
func (t *adaIDNATables) mapRunes(in []rune) ([]rune, bool) {
	out := make([]rune, 0, len(in))
	for _, x := range in {
		status := t.lookup(uint32(x))
		switch {
		case status == idnaDisallowed:
			return nil, false
		case status == idnaValid:
			out = append(out, x)
		case int(status) >= len(t.utf8Mappings):
			return nil, false
		default:
			for p := int(status); p < len(t.utf8Mappings) && t.utf8Mappings[p] != 0; {
				var r rune
				r, p = adaUTF8Next(t.utf8Mappings, p)
				out = append(out, r)
			}
		}
	}
	return out, true
}

// adaUTF8Next is ada's utf8_next over its own (trusted) mapping strings.
func adaUTF8Next(b []byte, p int) (rune, int) {
	at := func(i int) rune {
		if i < len(b) {
			return rune(b[i])
		}
		return 0
	}
	b0 := at(p)
	switch {
	case b0 < 0x80:
		return b0, p + 1
	case b0 < 0xE0:
		return (b0&0x1F)<<6 | at(p+1)&0x3F, p + 2
	case b0 < 0xF0:
		return (b0&0x0F)<<12 | (at(p+1)&0x3F)<<6 | at(p+2)&0x3F, p + 3
	}
	return (b0&0x07)<<18 | (at(p+1)&0x3F)<<12 | (at(p+2)&0x3F)<<6 | at(p+3)&0x3F, p + 4
}

/* --------------------------- normalization (src/normalization.cpp) */

const (
	hangulSBase  = 0xAC00
	hangulLBase  = 0x1100
	hangulVBase  = 0x1161
	hangulTBase  = 0x11A7
	hangulLCount = 19
	hangulVCount = 21
	hangulTCount = 28
	hangulNCount = hangulVCount * hangulTCount
	hangulSCount = hangulLCount * hangulNCount
)

func isHangulSyllable(c rune) bool { return c >= hangulSBase && c < hangulSBase+hangulSCount }

// decompEntry is the [start, end) entry pair of c's decomposition row.
func (t *adaIDNATables) decompEntry(c rune) (uint16, uint16) {
	row := int(t.decompIndex[c>>8])
	if row >= adaDecompositionRows {
		row = 0
	}
	i := row*adaDecompositionCols + int(c%256)
	return t.decompBlock[i], t.decompBlock[i+1]
}

// canonicalDecompLength is ada's canonical_decomp_length (0 for a Hangul
// syllable, for no decomposition and for a compatibility-only one).
func (t *adaIDNATables) canonicalDecompLength(c rune) int {
	if isHangulSyllable(c) || c < 0 || c >= 0x110000 {
		return 0
	}
	d0, d1 := t.decompEntry(c)
	n := int(d1>>2) - int(d0>>2)
	if n > 0 && d0&1 != 0 {
		n = 0
	}
	return n
}

// decompose is ada's compute_decomposition_length and decompose: Hangul
// syllables in full, everything else by one table lookup (the table holds
// full canonical decompositions).
func (t *adaIDNATables) decompose(in []rune) []rune {
	out := make([]rune, 0, len(in)+8)
	for _, c := range in {
		switch {
		case isHangulSyllable(c):
			s := c - hangulSBase
			out = append(out, hangulLBase+s/hangulNCount, hangulVBase+(s%hangulNCount)/hangulTCount)
			if s%hangulTCount != 0 {
				out = append(out, hangulTBase+s%hangulTCount)
			}
		case c >= 0 && c < 0x110000:
			if n := t.canonicalDecompLength(c); n > 0 {
				d0, _ := t.decompEntry(c)
				base := int(d0 >> 2)
				out = append(out, t.decompData[base:base+n]...)
			} else {
				out = append(out, c)
			}
		default:
			out = append(out, c)
		}
	}
	return out
}

// ccc is ada's get_ccc.
func (t *adaIDNATables) ccc(c rune) uint8 {
	if c < 0 || c >= 0x110000 {
		return 0
	}
	row := int(t.cccIndex[c>>8])
	if row >= adaCCCRows {
		row = 0
	}
	return t.cccBlock[row*adaCCCCols+int(c%256)]
}

// sortMarks is ada's sort_marks: an insertion sort of each run of marks by
// combining class.
func (t *adaIDNATables) sortMarks(s []rune) {
	for idx := 1; idx < len(s); idx++ {
		ccc := t.ccc(s[idx])
		if ccc == 0 {
			continue
		}
		cur := s[idx]
		back := idx
		for back != 0 && t.ccc(s[back-1]) > ccc {
			s[back] = s[back-1]
			back--
		}
		s[back] = cur
	}
}

// compEntry is the [start, end) range of c's composition pairs in compData.
func (t *adaIDNATables) compEntry(c rune) (int, int) {
	row := int(t.compIndex[c>>8])
	if row >= adaCompositionRows {
		row = 0
	}
	i := row*adaCompositionCols + int(c%256)
	return int(t.compBlock[i]), int(t.compBlock[i+1])
}

// composeWith is ada's binary search of x among the (second, composite)
// pairs in [left, right): the composite, or false.
func (t *adaIDNATables) composeWith(left, right int, x rune) (rune, bool) {
	if left < 0 || right < left || right > len(t.compData) {
		return 0, false
	}
	for left+2 < right {
		middle := left + (((right - left) >> 1) &^ 1)
		if t.compData[middle] <= x {
			left = middle
		}
		if t.compData[middle] >= x {
			right = middle
		}
	}
	if left+1 < len(t.compData) && t.compData[left] == x {
		return t.compData[left+1], true
	}
	return 0, false
}

// wouldCompose is ada's would_compose, Hangul conditions included: it
// checks an LV syllable followed by a T jamo with the test of an LVT
// syllable, so ada never composes a precomposed LV syllable with a T.
func (t *adaIDNATables) wouldCompose(s []rune) bool {
	for i := 0; i < len(s); {
		cur := s[i]
		switch {
		case cur >= hangulLBase && cur < hangulLBase+hangulLCount:
			if i+1 < len(s) && s[i+1] >= hangulVBase && s[i+1] < hangulVBase+hangulVCount {
				return true
			}
			i++
		case isHangulSyllable(cur):
			if (cur-hangulSBase)%hangulTCount != 0 && i+1 < len(s) &&
				s[i+1] > hangulTBase && s[i+1] < hangulTBase+hangulTCount {
				return true
			}
			i++
		case cur >= 0 && cur < 0x110000:
			left, right := t.compEntry(cur)
			previousCCC := -1
			j := i
			for ; j+1 < len(s); j++ {
				ccc := t.ccc(s[j+1])
				if right != left && previousCCC < int(ccc) {
					if left < 0 || right < left || right > len(t.compData) {
						break
					}
					if _, ok := t.composeWith(left, right, s[j+1]); ok {
						return true
					}
				}
				if ccc == 0 {
					break
				}
				previousCCC = int(ccc)
			}
			i = j + 1
		default:
			i++
		}
	}
	return false
}

// isAlreadyNFC is ada's is_already_nfc: no singleton decomposition, marks
// in order, and no pairwise composition. It is a quick check, and it can
// report a string NFC that is not (U+00E2 U+0323, U+AC00 U+11A8); ada then
// leaves the string as it is, and so does the port.
func (t *adaIDNATables) isAlreadyNFC(s []rune) bool {
	if len(s) == 0 {
		return true
	}
	for _, c := range s {
		if t.canonicalDecompLength(c) == 1 {
			return false
		}
	}
	prev := uint8(0)
	for _, c := range s {
		ccc := t.ccc(c)
		if ccc != 0 && prev > ccc {
			return false
		}
		prev = ccc
	}
	return !t.wouldCompose(s)
}

// compose is ada's compose, in place; it returns the composed prefix.
func (t *adaIDNATables) compose(s []rune) []rune {
	in, out := 0, 0
	for ; in < len(s); in, out = in+1, out+1 {
		s[out] = s[in]
		c := s[in]
		switch {
		case c >= hangulLBase && c < hangulLBase+hangulLCount:
			if in+1 < len(s) && s[in+1] >= hangulVBase && s[in+1] < hangulVBase+hangulVCount {
				s[out] = hangulSBase + ((c-hangulLBase)*hangulVCount+s[in+1]-hangulVBase)*hangulTCount
				in++
				if in+1 < len(s) && s[in+1] > hangulTBase && s[in+1] < hangulTBase+hangulTCount {
					in++
					s[out] += s[in] - hangulTBase
				}
			}
		case isHangulSyllable(c):
			if (c-hangulSBase)%hangulTCount != 0 && in+1 < len(s) &&
				s[in+1] > hangulTBase && s[in+1] < hangulTBase+hangulTCount {
				in++
				s[out] += s[in] - hangulTBase
			}
		case c >= 0 && c < 0x110000:
			left, right := t.compEntry(c)
			initial := out
			for previousCCC := -1; in+1 < len(s); in++ {
				ccc := t.ccc(s[in+1])
				if right != left && previousCCC < int(ccc) {
					if left < 0 || right < left || right > len(t.compData) {
						break
					}
					if composed, ok := t.composeWith(left, right, s[in+1]); ok {
						s[initial] = composed
						left, right = t.compEntry(composed)
						continue
					}
				}
				if ccc == 0 {
					break
				}
				previousCCC = int(ccc)
				out++
				s[out] = s[in+1]
			}
		}
	}
	if out < in {
		return s[:out]
	}
	return s
}

// normalize is ada's normalize: nothing when isAlreadyNFC says so, else
// decompose, order the marks and compose.
func (t *adaIDNATables) normalize(s []rune) []rune {
	if t.isAlreadyNFC(s) {
		return s
	}
	d := t.decompose(s)
	t.sortMarks(d)
	return t.compose(d)
}

/* -------------------------------------- validity (src/validity.cpp) */

// ada's Bidi classes (enum direction); a code point its table lacks is
// adaNone.
const (
	adaNone uint8 = iota
	adaBN
	adaCS
	adaES
	adaON
	adaEN
	adaL
	adaR
	adaNSM
	adaAL
	adaAN
	adaET
)

// direction is ada's find_direction.
func (t *adaIDNATables) direction(c rune) uint8 {
	cp := uint32(c)
	lo, hi := 0, len(t.dirFinal)
	for lo < hi {
		mid := lo + (hi-lo)/2
		if t.dirFinal[mid] < cp {
			lo = mid + 1
		} else {
			hi = mid
		}
	}
	if lo == len(t.dirFinal) || cp < t.dirStart[lo] {
		return adaNone
	}
	return t.dirValue[lo]
}

// isCombiningMark is ada's leading-mark test: c lies in one of its
// combining ranges.
func (t *adaIDNATables) isCombiningMark(c rune) bool {
	cp := uint32(c)
	lo, hi := 0, len(t.combining)/2
	for lo < hi {
		mid := lo + (hi-lo)/2
		if t.combining[2*mid+1] < cp {
			lo = mid + 1
		} else {
			hi = mid
		}
	}
	return lo < len(t.combining)/2 && cp >= t.combining[2*lo]
}
